(* [comment removed for export] *)
Definition rs_W (lo : Z) (sp : word) (a msz pa nch lst TH : Z) : list ivl :=
  [(lo, bv_unsigned sp); (1221064, 1221680); (pa, pa + 8 * nch); (a, a + msz); (lst + 24, lst + 32); (sh a, sh a + msz / 8); (TH + 2800, TH + 3168)]%Z.

(* [comment removed for export] *)
Definition rs_chunks (chunks : list Z) (idx nch lst : Z) : list Z :=
  if idx =? nch - 1 then chunks else firstn (Z.to_nat idx) chunks ++ lst :: skipn (S (Z.to_nat idx)) chunks.

(* [comment removed for export] *)
Definition recycle_sec_mid (L S Zr : list (word * word)) (mo : Model) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo a msz nres nch idx pa lst TSD CTX TH : Z) (chunks : list Z) (sbs : list byte) (g : word) (b244 : byte)
    (msF' : machine_state) (mo' : Model) : Prop :=
  exists (t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
       lzok bsegs L S Zr (mkCfg msF' mo')
    /\ restrict L S msF'
       = MS (mkR (wz 0x52a8c) (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 (wz a) (wz a) (wz a) (wz msz) (wz 0) a3 a4 a5 a6 a7
                 (wz msz) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
            F (Z_to_bv 64 0x075864) fc None m' (seg_rom bsegs)
    /\ same_but_materialized mo mo'
    /\ munch (rs_W lo sp a msz pa nch lst TH) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ SENV tp TSD CTX TH m' /\ RENV g b244 m'
    /\ stk bsegs m' lo (bv_unsigned sp + -32)
    /\ rw_cells bsegs m' (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells bsegs m' 1221016 [C8 (wz 4096); C8 (wz pa); C8 (wz pa)]
    /\ rw_cells bsegs m' 1221064 [C8 (wz nres); C8 (wz (nch - 1)); C8 (wz 0)]
    /\ stk bsegs m' 1221088 1221632 /\ rw_cells bsegs m' 1221632 [C8 (wz 0)] /\ stk bsegs m' 1221640 1221680
    /\ u64arr bsegs m' pa (wlist (rs_chunks chunks idx nch lst))
    /\ rw_cells bsegs m' a [C8 (wz a); C8 (wz msz)]
    /\ rw_cells bsegs m' (lst + 24) [C8 (wz idx)]
    /\ stk bsegs m' (TH + 2800) (TH + 3168)
    /\ u8arr bsegs m' (sh a) sbs.

Section SecRecycle.
  Variables (L S Zr : list (word * word)) (msF : machine_state) (mo : Model) (Q : config -> Prop).
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem).
